    Bug 1990657 - Account Hub Address Book - Make sure back button is disabled when in loading state. r=freaktechnik


    **How to Test**
    - Enable account hub address book pref
    - Show account hub for address book by creating a new address book
    - Choose remote address book setup
    - Enter your email address
    - The back button should be disabled

    Differential Revision: https://phabricator.services.mozilla.com/D266072

diff --git a/mail/components/accountcreation/content/widgets/account-hub-footer.mjs b/mail/components/accountcreation/content/widgets/account-hub-footer.mjs
index 2355a3012c8..4d713f5a1db 100644
--- a/mail/components/accountcreation/content/widgets/account-hub-footer.mjs
+++ b/mail/components/accountcreation/content/widgets/account-hub-footer.mjs
@@ -60,6 +60,10 @@ class AccountHubFooter extends HTMLElement {
     this.querySelector("#forward").disabled = value || this.disabled;
   }

+  toggleBackDisabled(value) {
+    this.querySelector("#back").disabled = value;
+  }
+
   canCustom(value) {
     const customAction = this.querySelector("#custom");
     customAction.hidden = !value;
diff --git a/mail/components/accountcreation/views/address-book.mjs b/mail/components/accountcreation/views/address-book.mjs
index 02ff6115845..991ec846886 100644
--- a/mail/components/accountcreation/views/address-book.mjs
+++ b/mail/components/accountcreation/views/address-book.mjs
@@ -472,6 +472,7 @@ class AccountHubAddressBook extends HTMLElement {
     this.#states.syncAddressBooksSubview.previousStep = previousStep;
     this.classList.add("busy");
     this.#footer.disabled = true;
+    this.#footer.toggleBackDisabled(true);
     this.#currentSubview.showNotification({
       fluentTitleId: "address-book-finding-remote-address-books",
       type: "info",
@@ -514,6 +515,7 @@ class AccountHubAddressBook extends HTMLElement {
       });
     } finally {
       this.#footer.disabled = false;
+      this.#footer.toggleBackDisabled(false);
       this.classList.remove("busy");
     }
   }
